/**
 * Booking references — the short number a guest quotes ("HB-7K4M2Q").
 *
 * The value is generated by the database (see
 * prisma/manual/002_booking_reference.sql), so this module only deals with
 * reading what a guest typed. People retype these off a printed slip or an SMS,
 * so be generous: lowercase, a missing prefix, spaces and stray dashes all
 * resolve to the same reference.
 */

export const BOOKING_REF_PREFIX = 'HB-'

/**
 * Exactly the alphabet the generator uses. 0/O and 1/I/L are absent by design,
 * so a reference read aloud can't come back as a different one.
 */
const REF_BODY = /^[2-9ABCDEFGHJKMNPQRSTUVWXYZ]{6}$/

/**
 * Canonical reference for whatever the guest typed, or null when it doesn't
 * look like a reference at all — the caller should then try it as a booking id.
 */
export function normalizeBookingRef(input: string): string | null {
  const cleaned = input
    .toUpperCase()
    // Drop spaces, dashes of every flavour, and anything else decorative.
    .replace(/[^0-9A-Z]/g, '')
    .replace(/^HB/, '')

  if (!REF_BODY.test(cleaned)) return null
  return BOOKING_REF_PREFIX + cleaned
}
